mapper.update:
update clazz
name = #{name}, room = #{room}, begin_date = #{beginDate}, end_date = #{endDate}, master_id = #{masterId}, subject = #{subject}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select c.*, e.name as masterName, (case when c.begin_date > curdate() then '未开班' when c.end_date < curdate() then '已结课' else '在读中' end) as status from clazz as c left join emp as e on c.master_id = e.id
and c.name like concat('%', #{name}, '%')
and c.begin_date >= #{begin}
and c.end_date <= #{end}
order by c.update_time desc
